{"command":"# Analyze xvic screenshot for structure: find brightest region (paper phosphor)
Add-Type -AssemblyName System.Drawing
$bmp = [System.Drawing.Bitmap]::FromFile("F:\GitHub\vice-sharp\docs\xvic-ready-pal-2026-08-08.png")
