  for ($x=$minx; $x -le $maxx; $x+=1) {
    $c=$bmp.GetPixel($x,$y)
    $lum = 0.299*$c.R + 0.587*$c.G + 0.114*$c.B
    if ($lum -lt 80 -and $lum -gt 10) { $dark++ }
  }
}
Write-Host "dark_on_paper~$dark"
$bmp.Dispose()
","description":"Analyze xvic READY geometry under CRT"}

